    # Detections already unpaired: count the reports as the pairing did, within 3 km and ±2 h of the
    # middle of the acquisition.
    op.execute(
        """
        UPDATE sar_detections d
        SET ais_reports_nearby = (
            SELECT count(*) FROM positions p
            WHERE p.received_at BETWEEN s.acquired_from + (s.acquired_to - s.acquired_from) / 2 - interval '2 hours'
                                    AND s.acquired_from + (s.acquired_to - s.acquired_from) / 2 + interval '2 hours'
              AND ST_DWithin(p.geom, d.geom, 3000)
        )
        FROM sar_scenes s
        WHERE s.id = d.scene_id AND d.status IN ('dark', 'no_coverage')
        """
    )
    # Live passes so far were announced frame by frame, as each was processed.
    op.execute(
        """
        UPDATE sar_scenes SET notified_at = processed_at
        WHERE status = 'processed' AND acquired_from >= (SELECT min(connected_at) FROM ingest_sessions)
        """
    )


